// Échéances trimestrielles auto-entrepreneur : 31/01, 30/04, 31/07, 31/10
const now = new Date();
const annee = now.getFullYear();
const echeances = [
  { date: new Date(annee, 0, 31), tDebut: new Date(annee - 1, 9, 1), tFin: new Date(annee, 0, 1) },
  { date: new Date(annee, 3, 30), tDebut: new Date(annee, 0, 1), tFin: new Date(annee, 3, 1) },
  { date: new Date(annee, 6, 31), tDebut: new Date(annee, 3, 1), tFin: new Date(annee, 6, 1) },
  { date: new Date(annee, 9, 31), tDebut: new Date(annee, 6, 1), tFin: new Date(annee, 9, 1) },
  { date: new Date(annee + 1, 0, 31), tDebut: new Date(annee, 9, 1), tFin: new Date(annee + 1, 0, 1) },
];
const prochaine = echeances.find(e => e.date >= new Date(now.toDateString()));
const dansJours = Math.round((prochaine.date - new Date(now.toDateString())) / 86400000);
if (![10, 3, 0].includes(dansJours)) return [];
const iso = d => d.toISOString().split('T')[0];
return [{ json: {
  echeance: iso(prochaine.date), dans_jours: dansJours,
  periode_debut: iso(prochaine.tDebut), periode_fin: iso(prochaine.tFin)
} }];

const e = $('Prochaine échéance URSSAF').first().json;
const ca = $input.first().json.ca || 0;
const taux = Number($env.TAUX_COTISATIONS_URSSAF || 0.212);
return [{ json: {
  ...e,
  ca: Math.round(ca * 100) / 100,
  nb_factures: $input.first().json.nb_factures,
  taux_pct: Math.round(taux * 1000) / 10,
  cotisations: Math.round(ca * taux * 100) / 100
} }];
